class MinStack {
    private Deque<Integer> stack;
    private Deque<Integer> minStack;
    public MinStack() { stack = new ArrayDeque<>(); minStack = new ArrayDeque<>(); }
    public void push(int val) { stack.push(val); if (minStack.isEmpty() || val <= minStack.peek()) minStack.push(val); }
    public void pop() { int val = stack.pop(); if (val == minStack.peek()) minStack.pop(); }
    public int top() { return stack.peek(); }
    public int getMin() { return minStack.peek(); }
}
